13	const ALGORITHM_SPECS = new Map([
14	  [HS256, { name: HS256, hashFn: sha256, blockSize: SHA256_BLOCK_SIZE, hmac: hmacSha256 }],
15	  [HS384, { name: HS384, hashFn: sha384, blockSize: SHA512_BLOCK_SIZE, hmac: hmacSha384 }],
16	  [HS512, { name: HS512, hashFn: sha512, blockSize: SHA512_BLOCK_SIZE, hmac: hmacSha512 }],
17	]);
18	
19	const SUPPORTED = new Set([HS256, HS384, HS512]);
20	
21	// alg -> hash function, used for the `at_hash` claim.
22	const HASHES = new Map([
23	  [HS256, sha256],
24	  [HS384, sha384],
25	  [HS512, sha512],
26	]);
