28	export const ALGORITHMS = Object.freeze({
29	  HS256,
30	  HS384,
31	  HS512,
32	  NONE: 'none',
33	  HMAC: new Set([HS256, HS384, HS512]),
34	  SUPPORTED,
35	  ALL: new Set([HS256, HS384, HS512]),
36	  HASHES,
37	});
