9	
10	/**
11	 * Iterate `[key, value]` pairs of a Map or a plain object.
12	 * @param {Map<*,*>|Object} obj
13	 * @returns {Array<[*, *]>}
14	 */
15	function entriesOf(obj) {
16	  if (obj instanceof Map) return [...obj.entries()];
17	  if (Array.isArray(obj)) return obj.map((pair) => [pair[0], pair[1]]);
18	  return Object.keys(obj).map((k) => [k, obj[k]]);
