23	 * HMACKey does the same); an `oct` JWK (Map/object with `k`) is base64url
24	 * decoded.
25	 * @param {string|Uint8Array|Array<number>|Map<*,*>|Object} key
26	 * @returns {Uint8Array}
27	 */
28	function toKeyBytes(key) {
29	  if (key instanceof Uint8Array) return key;
30	  if (typeof key === 'string') return encodeUtf8(key);
31	  if (Array.isArray(key)) return new Uint8Array(key);
32	  if (key instanceof Map) {
33	    if (key.has('k')) return base64UrlDecode(String(key.get('k')));
34	    throw new JWSError('Invalid JWK: missing "k" parameter');
35	  }
36	  if (key && typeof key === 'object') {
37	    if ('k' in key) return base64UrlDecode(String(key.k));
38	    throw new JWSError('Invalid JWK: missing "k" parameter');
39	  }
40	  if (key === null || key === undefined) return new Uint8Array(0);
41	  throw new JWSError('Unable to interpret key as an HMAC secret');
