47	 * @param {string} algorithm
48	 * @param {Map<*,*>|Object|null} additionalHeaders
49	 * @returns {string}
50	 */
51	function encodeHeader(algorithm, additionalHeaders) {
52	  const header = new Map([
53	    ['typ', 'JWT'],
54	    ['alg', algorithm],
55	  ]);
56	  if (additionalHeaders) {
57	    for (const [k, v] of entriesOf(additionalHeaders)) header.set(k, v);
58	  }
59	  const json = pyJsonDumps(header, {
60	    ensureAscii: true,
61	    separators: [',', ':'],
62	    sortKeys: true,
63	  });
