73	  if (typeof payload === 'string') return base64UrlEncode(encodeUtf8(payload));
74	  if (payload instanceof Map || Array.isArray(payload) || (payload && typeof payload === 'object')) {
75	    const json = pyJsonDumps(payload, {
76	      ensureAscii: true,
77	      separators: [',', ':'],
78	      sortKeys: false,
79	    });
80	    return base64UrlEncode(encodeUtf8(json));
81	  }
82	  throw new JWSError('Unable to encode payload: unsupported type');
83	}
