85	/**
86	 * Sign a payload, producing a compact JWS.
87	 *
88	 * @param {Uint8Array|string|Map<*,*>|Object} payload
89	 * @param {string|Uint8Array|Map<*,*>|Object} key
90	 * @param {{headers?: Map<*,*>|Object|null, algorithm?: string}} [opts]
