95	  if (!spec || !ALGORITHMS.SUPPORTED.has(algorithm)) {
96	    throw new JWSAlgorithmError('Algorithm ' + algorithm + ' not supported.');
97	  }
98	  const encodedHeader = encodeHeader(algorithm, headers);
99	  const encodedPayload = encodePayload(payload);
100	  const signingInput = encodedHeader + '.' + encodedPayload;
101	  const signature = spec.hmac(toKeyBytes(key), encodeUtf8(signingInput));
102	  return signingInput + '.' + base64UrlEncode(signature);
