117	  // Extra dots stay inside the claims segment (python-jose rsplits on the last
118	  // dot first), which then fails to decode -- same behavior, same error.
119	  const claimsSegment = parts.slice(1, parts.length - 1).join('.');
120	  const signatureSegment = parts[parts.length - 1];
121	  const signingInput = headerSegment + '.' + claimsSegment;
122	
123	  let headerData;
124	  try {
125	    headerData = base64UrlDecode(headerSegment);
126	  } catch (e) {
127	    throw new JWSError('Invalid header padding');
128	  }
129	
130	  let header;
131	  try {
132	    header = pyJsonLoads(decodeUtf8(headerData));
133	  } catch (e) {
134	    throw new JWSError('Invalid header string: ' + (e && e.message ? e.message : String(e)));
135	  }
136	  if (!(header instanceof Map)) {
137	    throw new JWSError('Invalid header string: must be a json object');
138	  }
139	
140	  let payload;
141	  try {
142	    payload = base64UrlDecode(claimsSegment);
143	  } catch (e) {
144	    throw new JWSError('Invalid payload padding');
145	  }
146	
147	  let signature;
148	  try {
149	    signature = base64UrlDecode(signatureSegment);
150	  } catch (e) {
151	    throw new JWSError('Invalid signature padding');
152	  }
