163	 */
164	function verifySignature(signingInput, header, signature, key, algorithms) {
165	  const alg = header.get('alg');
166	  if (!alg) {
167	    throw new JWSAlgorithmError('No algorithm was specified in the JWS header.');
168	  }
169	  if (algorithms !== null && algorithms !== undefined) {
170	    const allowed = typeof algorithms === 'string' ? [algorithms] : Array.from(algorithms);
171	    if (!allowed.includes(alg)) {
172	      throw new JWSAlgorithmError('The specified alg value is not allowed');
173	    }
174	  }
175	  const spec = getAlgorithmSpec(alg);
176	  if (!spec) {
177	    throw new JWSAlgorithmError('Invalid or unsupported algorithm: ' + alg);
178	  }
179	  const expected = spec.hmac(toKeyBytes(key), encodeUtf8(signingInput));
180	  // Constant-time comparison (length-checked) from the codec module.
181	  if (!bytesEqual(expected, signature)) {
182	    throw new JWSSignatureError('Signature verification failed.');
183	  }
