186	/**
187	 * Verify a compact JWS and return its raw payload bytes.
188	 *
189	 * @param {string|Uint8Array} token
190	 * @param {string|Uint8Array|Map<*,*>|Object} key
191	 * @param {Array<string>|Set<string>|string|null} [algorithms]
192	 * @param {boolean} [verifyFlag] when false the signature is not checked
193	 * @returns {Uint8Array}
194	 */
195	export function verify(token, key, algorithms = null, verifyFlag = true) {
196	  const loaded = load(token);
197	  if (verifyFlag) {
198	    verifySignature(loaded.signingInput, loaded.header, loaded.signature, key, algorithms);
199	  }
200	  return loaded.payload;
201	}
