1	// JWT (JSON Web Token) encode/decode, mirroring python-jose's `jose.jwt`.
2	
3	import { encodeUtf8, decodeUtf8 } from '../codec/bytes.mjs';
4	import { base64UrlEncode } from '../codec/base64url.mjs';
5	import { pyJsonDumps, pyJsonLoads } from '../py/pyjson.mjs';
6	import { ALGORITHMS } from './constants.mjs';
7	import * as jws from './jws.mjs';
8	import { JWSError, JWTError, JWTClaimsError, ExpiredSignatureError } from './errors.mjs';
9	
10	/** Option defaults, matching python-jose. */
11	const DEFAULT_OPTIONS = {
12	  verify_signature: true,
13	  verify_aud: true,
14	  verify_iat: true,
15	  verify_exp: true,
16	  verify_nbf: true,
17	  verify_iss: true,
18	  verify_sub: true,
19	  verify_jti: true,
20	  verify_at_hash: true,
21	  require_aud: false,
22	  require_iat: false,
23	  require_exp: false,
24	  require_nbf: false,
25	  require_iss: false,
26	  require_sub: false,
27	  require_jti: false,
28	  require_at_hash: false,
29	  leeway: 0,
30	};
31	
32	/**
33	 * @param {Map<*,*>|Object} obj
34	 * @returns {Array<[*, *]>}
35	 */
36	function entriesOf(obj) {
37	  if (obj instanceof Map) return [...obj.entries()];
38	  return Object.keys(obj).map((k) => [k, obj[k]]);
39	}
40	
41	/**
42	 * Copy claims into a Map, preserving insertion order.
43	 * @param {Map<*,*>|Object} claims
44	 * @returns {Map<*,*>}
45	 */
46	function toClaimsMap(claims) {
47	  if (claims instanceof Map) return new Map(claims);
48	  if (claims && typeof claims === 'object' && !Array.isArray(claims)) {
49	    return new Map(entriesOf(claims));
50	  }
51	  throw new JWTError('Claims must be a dict (Map) or a plain object');
52	}
53	
54	/** Current time as Unix epoch seconds (UTC), like Python's timegm(utcnow()). */
55	function nowEpochSeconds() {
56	  return Math.floor(Date.now() / 1000);
57	}
58	
59	/**
60	 * Python's `int(x)` for the values our data model can hold.
61	 * Returns null when Python would have raised (i.e. the claim is not numeric).
62	 * @param {*} value
63	 * @returns {bigint|null}
64	 */
65	function asInt(value) {
66	  if (typeof value === 'bigint') return value;
67	  if (typeof value === 'boolean') return value ? 1n : 0n;
68	  if (typeof value === 'number') {
69	    if (!Number.isFinite(value)) return null;
70	    return BigInt(Math.trunc(value));
71	  }
72	  if (typeof value === 'string') {
73	    const t = value.trim();
74	    if (/^[+-]?\d+$/.test(t)) return BigInt(t);
75	    return null;
76	  }
77	  return null;
78	}
79	
80	/**
81	 * Left half of the digest of `accessToken`, base64url encoded (OIDC at_hash).
82	 * @param {string} accessToken
83	 * @param {string} algorithm
84	 * @returns {string}
85	 */
86	export function calculateAtHash(accessToken, algorithm) {
87	  const hashFn = ALGORITHMS.HASHES.get(algorithm);
88	  if (!hashFn) {
89	    throw new JWTClaimsError('Unable to calculate at_hash to verify against token claims.');
90	  }
91	  const digest = hashFn(encodeUtf8(String(accessToken)));
92	  const cutAt = Math.floor(digest.length / 2);
93	  return base64UrlEncode(digest.subarray(0, cutAt));
94	}
