96	// ---------------------------------------------------------------------------
97	// encode
98	// ---------------------------------------------------------------------------
99	
100	/**
101	 * Encode claims into a signed compact JWT.
102	 *
103	 * The claims are serialized with insertion order preserved (NOT sorted) --
104	 * only the header is sorted.
105	 *
106	 * @param {Map<*,*>|Object} claims dict-like; ints should be BigInt
107	 * @param {string|Uint8Array|Map<*,*>|Object} key
108	 * @param {string} [algorithm]
109	 * @param {Map<*,*>|Object|null} [headers] extra header parameters
110	 * @param {string|null} [accessToken] when set, an `at_hash` claim is added
111	 * @returns {string}
112	 */
113	export function encode(
114	  claims,
115	  key,
116	  algorithm = ALGORITHMS.HS256,
117	  headers = null,
118	  accessToken = null,
119	) {
120	  const working = toClaimsMap(claims);
121	
122	  // Known time claims given as Date objects become epoch-second ints.
123	  for (const timeClaim of ['exp', 'iat', 'nbf']) {
124	    const value = working.get(timeClaim);
125	    if (value instanceof Date) {
126	      working.set(timeClaim, BigInt(Math.floor(value.getTime() / 1000)));
127	    }
128	  }
129	
130	  if (accessToken) {
131	    working.set('at_hash', calculateAtHash(accessToken, algorithm));
132	  }
133	
134	  const payload = pyJsonDumps(working, {
135	    ensureAscii: true,
136	    separators: [',', ':'],
137	    sortKeys: false,
138	  });
139	
140	  return jws.sign(payload, key, { headers, algorithm });
141	}
