147	/**
148	 * Verify and decode a compact JWT.
149	 *
150	 * @param {string|Uint8Array} token
151	 * @param {string|Uint8Array|Map<*,*>|Object} key
152	 * @param {{algorithms?: Array<string>|Set<string>|string|null,
153	 *          options?: Map<*,*>|Object|null,
154	 *          audience?: string|null, issuer?: string|Array<string>|null,
155	 *          subject?: string|null, accessToken?: string|null}} [opts]
156	 * @returns {Map<*,*>} the claims, key order preserved
157	 */
158	export function decode(
159	  token,
160	  key,
161	  { algorithms = null, options = null, audience = null, issuer = null, subject = null, accessToken = null } = {},
162	) {
163	  const merged = { ...DEFAULT_OPTIONS };
164	  if (options) {
165	    for (const [k, v] of entriesOf(options)) merged[String(k)] = v;
166	  }
167	
168	  const verifySignature = merged.verify_signature === undefined ? true : !!merged.verify_signature;
169	
170	  // Signature/segment problems surface as JWTError carrying the original
171	  // message, mirroring `except JWSError as e: raise JWTError(e)`.
172	  let payload;
173	  try {
174	    payload = jws.verify(token, key, algorithms, verifySignature);
175	  } catch (e) {
176	    if (e instanceof JWSError) throw new JWTError(e.message);
177	    throw e;
178	  }
179	
180	  // The header's alg is needed to verify `at_hash`.
181	  const algorithm = jws.getUnverifiedHeader(token).get('alg');
182	
183	  let claims;
184	  try {
185	    claims = pyJsonLoads(decodeUtf8(payload));
186	  } catch (e) {
187	    throw new JWTError('Invalid payload string: ' + (e && e.message ? e.message : String(e)));
188	  }
189	  if (!(claims instanceof Map)) {
190	    throw new JWTError('Invalid payload string: must be a json object');
191	  }
192	
193	  validateClaims(claims, {
194	    audience,
195	    issuer,
196	    subject,
197	    algorithm,
198	    accessToken,
199	    options: merged,
200	  });
201	
202	  return claims;
203	}
204	
205	/**
206	 * Run every enabled claim check, in python-jose's order.
207	 * @param {Map<*,*>} claims
208	 * @param {{audience?: *, issuer?: *, subject?: *, algorithm?: *, accessToken?: *, options: Object}} ctx
209	 */
210	export function validateClaims(claims, ctx = { options: {} }) {
211	  const options = { ...DEFAULT_OPTIONS, ...(ctx.options || {}) };
212	  const leeway = Number(options.leeway || 0);
213	
214	  // require_* first: a missing required claim is fatal, and a present one
215	  // forces its verify_* counterpart on.
216	  for (const optionName of Object.keys(options)) {
217	    if (!optionName.startsWith('require_') || !options[optionName]) continue;
218	    const claimName = optionName.slice('require_'.length);
219	    if (!claims.has(claimName)) {
220	      throw new JWTClaimsError('missing ' + claimName + ' claim');
221	    }
222	    options['verify_' + claimName] = true;
223	  }
224	
225	  const audience = ctx.audience === undefined ? null : ctx.audience;
226	  if (!(audience === null || typeof audience === 'string')) {
227	    throw new JWTError('audience must be a string or None');
228	  }
229	
230	  if (options.verify_iat) validateIat(claims);
231	  if (options.verify_nbf) validateNbf(claims, leeway);
232	  if (options.verify_exp) validateExp(claims, leeway);
233	  if (options.verify_aud) validateAud(claims, audience);
234	  if (options.verify_iss) validateIss(claims, ctx.issuer === undefined ? null : ctx.issuer);
235	  if (options.verify_sub) validateSub(claims, ctx.subject === undefined ? null : ctx.subject);
236	  if (options.verify_jti) validateJti(claims);
237	  if (options.verify_at_hash) validateAtHash(claims, ctx.accessToken, ctx.algorithm);
238	}
239	
240	function validateIat(claims) {
241	  if (!claims.has('iat')) return;
242	  if (asInt(claims.get('iat')) === null) {
243	    throw new JWTClaimsError('Issued At claim (iat) must be an integer.');
244	  }
245	}
246	
247	function validateNbf(claims, leeway) {
248	  if (!claims.has('nbf')) return;
249	  const nbf = asInt(claims.get('nbf'));
250	  if (nbf === null) {
251	    throw new JWTClaimsError('Not Before claim (nbf) must be an integer.');
252	  }
253	  const now = nowEpochSeconds();
254	  if (Number(nbf) > now + leeway) {
255	    throw new JWTClaimsError('The token is not yet valid (nbf)');
256	  }
257	}
258	
259	function validateExp(claims, leeway) {
260	  if (!claims.has('exp')) return;
261	  const exp = asInt(claims.get('exp'));
262	  if (exp === null) {
263	    throw new JWTClaimsError('Expiration Time claim (exp) must be an integer.');
264	  }
265	  const now = nowEpochSeconds();
266	  if (Number(exp) < now - leeway) {
267	    throw new ExpiredSignatureError('Signature has expired.');
268	  }
269	}
270	
271	function validateAud(claims, audience) {
272	  // No `aud` claim at all: nothing to check, silently accept.
273	  if (!claims.has('aud')) return;
274	
275	  let audienceClaims = claims.get('aud');
276	  if (typeof audienceClaims === 'string') audienceClaims = [audienceClaims];
277	  if (!Array.isArray(audienceClaims)) {
278	    throw new JWTClaimsError('Invalid claim format in token');
279	  }
280	  for (const entry of audienceClaims) {
281	    if (typeof entry !== 'string') {
282	      throw new JWTClaimsError('Invalid claim format in token');
283	    }
284	  }
285	  if (!audienceClaims.includes(audience)) {
286	    throw new JWTClaimsError('Invalid audience');
287	  }
288	}
289	
290	function validateIss(claims, issuer) {
291	  if (issuer === null || issuer === undefined) return;
292	  const allowed = typeof issuer === 'string' ? [issuer] : Array.from(issuer);
293	  const value = claims.has('iss') ? claims.get('iss') : undefined;
294	  if (!allowed.includes(value)) {
295	    throw new JWTClaimsError('Invalid issuer');
296	  }
297	}
298	
299	function validateSub(claims, subject) {
300	  // No `sub` claim: nothing to check.
301	  if (!claims.has('sub')) return;
302	  if (typeof claims.get('sub') !== 'string') {
303	    throw new JWTClaimsError('Subject must be a string.');
304	  }
305	  // A string `sub` with no `subject` argument verifies silently.
306	  if (subject !== null && subject !== undefined) {
307	    if (claims.get('sub') !== subject) {
308	      throw new JWTClaimsError('Invalid subject');
309	    }
310	  }
311	}
312	
313	function validateJti(claims) {
314	  if (!claims.has('jti')) return;
315	  if (typeof claims.get('jti') !== 'string') {
316	    throw new JWTClaimsError('JWT ID must be a string.');
317	  }
318	}
319	
320	function validateAtHash(claims, accessToken, algorithm) {
321	  if (!claims.has('at_hash')) return;
322	  if (!accessToken) {
323	    throw new JWTClaimsError('No access_token provided to compare against at_hash claim.');
324	  }
325	  let expected;
326	  try {
327	    expected = calculateAtHash(accessToken, algorithm);
328	  } catch (e) {
329	    throw new JWTClaimsError('Unable to calculate at_hash to verify against token claims.');
330	  }
331	  if (claims.get('at_hash') !== expected) {
332	    throw new JWTClaimsError('at_hash claim does not match access_token.');
333	  }
334	}
