354	/**
355	 * Claims of a token without verifying it.
356	 * @param {string|Uint8Array} token
357	 * @returns {Map<*,*>}
358	 */
359	export function getUnverifiedClaims(token) {
360	  const payload = jws.getUnverifiedClaims(token);
361	  let claims;
362	  try {
363	    claims = pyJsonLoads(decodeUtf8(payload));
364	  } catch (e) {
365	    throw new JWTError('Invalid payload string: ' + (e && e.message ? e.message : String(e)));
366	  }
367	  if (!(claims instanceof Map)) {
368	    throw new JWTError('Invalid payload string: must be a json object');
369	  }
370	  return claims;
371	}
