1	// CPython `print()` reproduced in pure JavaScript.
2	
3	import { pyStr } from './pyrepr.mjs';
4	
5	/**
6	 * CPython `print(*values)`: joins str(v) with a single space and writes the
7	 * result plus a trailing newline to stdout, byte-for-byte like Python.
8	 *
9	 * @param {...*} values
10	 * @returns {void}
11	 */
12	export function pyPrint(...values) {
13	  let out = '';
14	  for (let i = 0; i < values.length; i++) {
15	    if (i > 0) out += ' ';
16	    out += pyStr(values[i]);
17	  }
18	  process.stdout.write(out + '\n');
19	}
