1	// CPython `repr()` / `str()` string-formatting reproduced in pure JavaScript.
2	//
3	// Data model convention (shared across this project):
4	//   dict -> Map, str -> string, int -> BigInt, float -> number,
5	//   bool -> boolean, None -> null, list -> Array.
6	//
7	// No external dependencies. ESM only.
8	
9	// ---------------------------------------------------------------------------
10	// str.isprintable()
11	// ---------------------------------------------------------------------------
12	
13	// CPython's Py_UNICODE_ISPRINTABLE(): a character is *not* printable when its
14	// Unicode general category is one of Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs.  The
15	// single exception is U+0020 SPACE, which Python treats as printable.
16	// Built once, at module scope.
17	const NONPRINTABLE_RE =
18	  /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
19	
20	/**
21	 * Returns true if every code point of `str` is printable in CPython's sense.
22	 * The empty string is printable (matching `''.isprintable() == True`).
23	 *
24	 * @param {string} str
25	 * @returns {boolean}
26	 */
27	export function isPrintable(str) {
28	  const s = String(str);
29	  for (const ch of s) {
30	    // U+0020 is the one member of Zs that Python considers printable.
31	    if (ch === ' ') continue;
32	    if (NONPRINTABLE_RE.test(ch)) return false;
33	  }
34	  return true;
35	}
36	
37	/**
38	 * Single-code-point variant of isPrintable(); `ch` must be one code point.
39	 *
40	 * @param {string} ch
41	 * @returns {boolean}
42	 */
43	function isPrintableChar(ch) {
44	  if (ch === ' ') return true;
45	  return !NONPRINTABLE_RE.test(ch);
46	}
47	
48	function hex(n, width) {
49	  return n.toString(16).padStart(width, '0');
50	}
51	
52	// ---------------------------------------------------------------------------
53	// repr(str)
54	// ---------------------------------------------------------------------------
55	
56	/**
57	 * CPython `repr()` of a `str`.
58	 *
59	 * Quote selection: `'` normally; `"` when the string contains `'` but no `"`.
60	 * Escapes: `\\`, the active quote, `\t`, `\n`, `\r`; every other
61	 * non-printable code point becomes `\xhh`, `\uhhhh` or `\Uhhhhhhhh`.
62	 * Printable code points (letters, CJK, emoji, combining marks, ...) are raw.
63	 *
64	 * @param {string} s
65	 * @returns {string}
66	 */
67	export function pyStrRepr(s) {
68	  const str = String(s);
69	
70	  let quote = "'";
71	  if (str.includes("'") && !str.includes('"')) quote = '"';
72	
73	  let out = quote;
74	  for (const ch of str) {
75	    if (ch === quote || ch === '\\') {
76	      out += '\\' + ch;
77	      continue;
78	    }
79	    if (ch === '\t') {
80	      out += '\\t';
81	      continue;
82	    }
83	    if (ch === '\n') {
84	      out += '\\n';
85	      continue;
86	    }
87	    if (ch === '\r') {
88	      out += '\\r';
89	      continue;
90	    }
91	    if (isPrintableChar(ch)) {
92	      out += ch;
93	      continue;
94	    }
95	    const cp = ch.codePointAt(0);
96	    if (cp <= 0xff) out += '\\x' + hex(cp, 2);
97	    else if (cp <= 0xffff) out += '\\u' + hex(cp, 4);
98	    else out += '\\U' + hex(cp, 8);
99	  }
100	  return out + quote;
101	}
102	
103	// ---------------------------------------------------------------------------
104	// repr(float)
105	// ---------------------------------------------------------------------------
106	
107	// `Number.prototype.toExponential()` called with no argument is specified to
108	// use "as many digits as necessary to uniquely specify the number", i.e. the
109	// same shortest-round-trip digit string CPython's repr() produces.
110	const EXP_RE = /^(-?)(\d)(?:\.(\d+))?e([+-]\d+)$/;
111	
112	/**
113	 * CPython `repr()` of a `float`.
114	 *
115	 * Shortest round-tripping digits, always with a fractional part in fixed
116	 * notation (`1.0`), exponential notation when the decimal point position is
117	 * <= -4 or > 16 (so 1e15 -> '1000000000000000.0' but 1e16 -> '1e+16', and
118	 * 0.0001 -> '0.0001' but 0.00001 -> '1e-05').  Exponents always carry a sign
119	 * and at least two digits.  Non-finite values are 'inf' / '-inf' / 'nan'.
120	 *
121	 * @param {number|bigint} value
122	 * @returns {string}
123	 */
124	export function pyFloatRepr(value) {
125	  const n = typeof value === 'bigint' ? Number(value) : Number(value);
126	
127	  if (Number.isNaN(n)) return 'nan';
128	  if (n === Infinity) return 'inf';
129	  if (n === -Infinity) return '-inf';
130	
131	  const neg = n < 0 || Object.is(n, -0);
132	  const abs = neg ? -n : n;
133	
134	  if (abs === 0) return neg ? '-0.0' : '0.0';
135	
136	  const m = EXP_RE.exec(abs.toExponential());
137	  if (m === null) {
138	    // Should be unreachable; fall back to a plain conversion.
139	    return (neg ? '-' : '') + String(abs);
140	  }
141	  const lead = m[2];
142	  const rest = m[3] || '';
143	  const digits = lead + rest;
144	  const exp10 = Number.parseInt(m[4], 10);
145	  // decpt: position of the decimal point relative to `digits`
146	  // (value === 0.DIGITS * 10**decpt).
147	  const decpt = exp10 + 1;
148	
149	  let out;
150	  if (decpt <= -4 || decpt > 16) {
151	    const sign = exp10 < 0 ? '-' : '+';
152	    out =
153	      lead +
154	      (rest ? '.' + rest : '') +
155	      'e' +
156	      sign +
157	      String(Math.abs(exp10)).padStart(2, '0');
158	  } else if (decpt <= 0) {
159	    out = '0.' + '0'.repeat(-decpt) + digits;
160	  } else if (decpt >= digits.length) {
161	    out = digits + '0'.repeat(decpt - digits.length) + '.0';
162	  } else {
163	    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
164	  }
165	  return neg ? '-' + out : out;
166	}
167	
168	// ---------------------------------------------------------------------------
169	// repr(int)
170	// ---------------------------------------------------------------------------
171	
172	/**
173	 * CPython `repr()` of an `int` (represented as a BigInt in this project).
174	 *
175	 * @param {bigint|number} value
176	 * @returns {string}
177	 */
178	export function pyIntRepr(value) {
179	  if (typeof value === 'bigint') return value.toString(10);
180	  const n = Number(value);
181	  if (!Number.isFinite(n)) return pyFloatRepr(n);
182	  if (Number.isInteger(n)) return BigInt(n).toString(10);
183	  return Math.trunc(n).toString(10);
184	}
185	
186	// ---------------------------------------------------------------------------
187	// repr(object) dispatch
188	// ---------------------------------------------------------------------------
189	
190	/**
191	 * CPython `repr()` for the project's data model.
192	 *
193	 * @param {*} value
194	 * @returns {string}
195	 */
196	export function pyRepr(value) {
197	  if (value === null || value === undefined) return 'None';
198	
199	  switch (typeof value) {
200	    case 'string':
201	      return pyStrRepr(value);
202	    case 'bigint':
203	      return pyIntRepr(value);
204	    case 'number':
205	      return pyFloatRepr(value);
206	    case 'boolean':
207	      return value ? 'True' : 'False';
208	    default:
209	      break;
210	  }
211	
212	  if (Array.isArray(value)) {
213	    let parts = '';
214	    for (let i = 0; i < value.length; i++) {
215	      if (i > 0) parts += ', ';
216	      parts += pyRepr(value[i]);
217	    }
218	    return '[' + parts + ']';
219	  }
220	
221	  if (value instanceof Map) {
222	    if (value.size === 0) return '{}';
223	    let parts = '';
224	    let first = true;
225	    for (const [k, v] of value) {
226	      if (!first) parts += ', ';
227	      first = false;
228	      parts += pyRepr(k) + ': ' + pyRepr(v);
229	    }
230	    return '{' + parts + '}';
231	  }
232	
233	  if (typeof value === 'object') {
234	    const keys = Object.keys(value);
235	    if (keys.length === 0) return '{}';
236	    let parts = '';
237	    for (let i = 0; i < keys.length; i++) {
238	      if (i > 0) parts += ', ';
239	      parts += pyRepr(keys[i]) + ': ' + pyRepr(value[keys[i]]);
240	    }
241	    return '{' + parts + '}';
242	  }
243	
244	  return String(value);
245	}
246	
247	/**
248	 * CPython `str()`: strings are returned unchanged, everything else uses repr().
249	 *
250	 * @param {*} value
251	 * @returns {string}
252	 */
253	export function pyStr(value) {
254	  if (typeof value === 'string') return value;
255	  return pyRepr(value);
256	}
