1	// CPython `json` module (dumps/loads) reproduced in pure JavaScript.
2	//
3	// Data model convention (shared across this project):
4	//   dict -> Map, str -> string, int -> BigInt, float -> number,
5	//   bool -> boolean, None -> null, list -> Array.
6	//
7	// Float formatting is delegated to pyFloatRepr() so the `repr()` logic lives
8	// in exactly one place.
9	
10	import { pyFloatRepr } from './pyrepr.mjs';
11	
12	// ---------------------------------------------------------------------------
13	// dumps
14	// ---------------------------------------------------------------------------
15	
16	// The short escapes used by CPython's C encoder.  Note that `/` is NOT escaped.
17	const SHORT_ESCAPES = new Map([
18	  ['"', '\\"'],
19	  ['\\', '\\\\'],
20	  ['\b', '\\b'],
21	  ['\t', '\\t'],
22	  ['\n', '\\n'],
23	  ['\f', '\\f'],
24	  ['\r', '\\r'],
25	]);
26	
27	function u4(code) {
28	  return '\\u' + code.toString(16).padStart(4, '0');
29	}
30	
31	/**
32	 * JSON string literal, byte-identical to CPython's C encoder.
33	 *
34	 * Iterates UTF-16 code units, so with ensureAscii an astral character becomes
35	 * a surrogate pair of two `\uxxxx` escapes (exactly what CPython emits).
36	 *
37	 * @param {string} s
38	 * @param {boolean} ensureAscii
39	 * @returns {string}
40	 */
41	export function pyJsonEncodeString(s, ensureAscii = true) {
42	  const str = String(s);
43	  let out = '"';
44	  for (let i = 0; i < str.length; i++) {
45	    const ch = str[i];
46	    const short = SHORT_ESCAPES.get(ch);
47	    if (short !== undefined) {
48	      out += short;
49	      continue;
50	    }
51	    const code = str.charCodeAt(i);
52	    if (code < 0x20) {
53	      out += u4(code);
54	    } else if (code > 0x7e && ensureAscii) {
55	      out += u4(code);
56	    } else {
57	      out += ch;
58	    }
59	  }
60	  return out + '"';
61	}
62	
63	function jsonFloat(n) {
64	  if (Number.isNaN(n)) return 'NaN';
65	  if (n === Infinity) return 'Infinity';
66	  if (n === -Infinity) return '-Infinity';
67	  return pyFloatRepr(n);
68	}
69	
70	function keyToString(key) {
71	  if (typeof key === 'string') return key;
72	  if (typeof key === 'bigint') return key.toString(10);
73	  if (typeof key === 'boolean') return key ? 'true' : 'false';
74	  if (key === null || key === undefined) return 'null';
75	  if (typeof key === 'number') return jsonFloat(key);
76	  throw new TypeError('keys must be str, int, float, bool or None');
77	}
78	
79	function entriesOf(value) {
80	  if (value instanceof Map) return [...value.entries()];
81	  return Object.keys(value).map((k) => [k, value[k]]);
82	}
83	
84	/**
85	 * CPython `json.dumps()`.
86	 *
87	 * @param {*} value
88	 * @param {{ensureAscii?: boolean, separators?: [string,string]|null,
89	 *          sortKeys?: boolean, indent?: number|bigint|string|null}} [options]
90	 * @returns {string}
91	 */
92	export function pyJsonDumps(value, options = {}) {
93	  const {
94	    ensureAscii = true,
95	    separators = null,
96	    sortKeys = false,
97	    indent = null,
98	  } = options || {};
99	
100	  let indentStr = null;
101	  if (indent !== null && indent !== undefined) {
102	    indentStr =
103	      typeof indent === 'string' ? indent : ' '.repeat(Number(indent));
104	  }
105	
106	  // CPython: default separators are (', ', ': '); when indent is given and no
107	  // separators are supplied, the item separator loses its trailing space.
108	  let itemSep = ', ';
109	  let keySep = ': ';
110	  if (separators !== null && separators !== undefined) {
111	    itemSep = separators[0];
112	    keySep = separators[1];
113	  } else if (indentStr !== null) {
114	    itemSep = ',';
115	  }
116	
117	  const seen = new Set();
118	
119	  function encode(v, level) {
120	    if (v === null || v === undefined) return 'null';
121	
122	    switch (typeof v) {
123	      case 'string':
124	        return pyJsonEncodeString(v, ensureAscii);
125	      case 'bigint':
126	        return v.toString(10);
127	      case 'number':
128	        return jsonFloat(v);
129	      case 'boolean':
130	        return v ? 'true' : 'false';
131	      default:
132	        break;
133	    }
134	
135	    if (typeof v !== 'object') {
136	      throw new TypeError(
137	        'Object of type ' + typeof v + ' is not JSON serializable',
138	      );
139	    }
140	
141	    if (seen.has(v)) throw new TypeError('Circular reference detected');
142	    seen.add(v);
143	    try {
144	      let newline = '';
145	      let closeNewline = '';
146	      if (indentStr !== null) {
147	        newline = '\n' + indentStr.repeat(level + 1);
148	        closeNewline = '\n' + indentStr.repeat(level);
149	      }
150	
151	      if (Array.isArray(v)) {
152	        if (v.length === 0) return '[]';
153	        const parts = v.map((item) => encode(item, level + 1));
154	        return '[' + newline + parts.join(itemSep + newline) + closeNewline + ']';
155	      }
156	
157	      const entries = entriesOf(v).map(([k, val]) => [keyToString(k), val]);
158	      if (entries.length === 0) return '{}';
159	      if (sortKeys) {
160	        // UTF-16 code-unit order, i.e. plain JS `<` on strings.
161	        entries.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
162	      }
163	      const parts = entries.map(
164	        ([k, val]) =>
165	          pyJsonEncodeString(k, ensureAscii) + keySep + encode(val, level + 1),
166	      );
167	      return '{' + newline + parts.join(itemSep + newline) + closeNewline + '}';
168	    } finally {
169	      seen.delete(v);
170	    }
171	  }
172	
173	  return encode(value, 0);
174	}
