176	// ---------------------------------------------------------------------------
177	// loads -- hand-rolled recursive-descent parser
178	// ---------------------------------------------------------------------------
179	
180	const WS = new Set([' ', '\t', '\n', '\r']);
181	
182	const STRING_ESCAPES = new Map([
183	  ['"', '"'],
184	  ['\\', '\\'],
185	  ['/', '/'],
186	  ['b', '\b'],
187	  ['f', '\f'],
188	  ['n', '\n'],
189	  ['r', '\r'],
190	  ['t', '\t'],
191	]);
192	
193	class JsonParser {
194	  constructor(text) {
195	    this.s = text;
196	    this.i = 0;
197	  }
198	
199	  fail(msg) {
200	    throw new Error(msg + ': line 1 column ' + (this.i + 1) + ' (char ' + this.i + ')');
201	  }
202	
203	  skipWs() {
204	    while (this.i < this.s.length && WS.has(this.s[this.i])) this.i++;
205	  }
206	
207	  peek() {
208	    return this.i < this.s.length ? this.s[this.i] : '';
209	  }
210	
211	  expect(ch) {
212	    if (this.s[this.i] !== ch) this.fail("Expecting '" + ch + "' delimiter");
213	    this.i++;
214	  }
215	
216	  literal(word) {
217	    if (this.s.startsWith(word, this.i)) {
218	      this.i += word.length;
219	      return true;
220	    }
221	    return false;
222	  }
223	
224	  parseValue() {
225	    this.skipWs();
226	    if (this.i >= this.s.length) this.fail('Expecting value');
227	    const ch = this.s[this.i];
228	    switch (ch) {
229	      case '{':
230	        return this.parseObject();
231	      case '[':
232	        return this.parseArray();
233	      case '"':
234	        return this.parseString();
235	      default:
236	        break;
237	    }
238	    if (this.literal('true')) return true;
239	    if (this.literal('false')) return false;
240	    if (this.literal('null')) return null;
241	    // CPython's json accepts these non-standard constants by default.
242	    if (this.literal('NaN')) return NaN;
243	    if (this.literal('Infinity')) return Infinity;
244	    if (this.literal('-Infinity')) return -Infinity;
245	    if (ch === '-' || (ch >= '0' && ch <= '9')) return this.parseNumber();
246	    this.fail('Expecting value');
247	    return undefined;
248	  }
249	
250	  parseObject() {
251	    this.expect('{');
252	    const map = new Map();
253	    this.skipWs();
254	    if (this.peek() === '}') {
255	      this.i++;
256	      return map;
257	    }
258	    for (;;) {
259	      this.skipWs();
260	      if (this.peek() !== '"') this.fail('Expecting property name enclosed in double quotes');
261	      const key = this.parseString();
262	      this.skipWs();
263	      this.expect(':');
264	      const value = this.parseValue();
265	      // Document order is preserved; a repeated key keeps its first position
266	      // (Map.set semantics) with the last value, exactly like CPython's dict.
267	      map.set(key, value);
268	      this.skipWs();
269	      const ch = this.peek();
270	      if (ch === ',') {
271	        this.i++;
272	        continue;
273	      }
274	      if (ch === '}') {
275	        this.i++;
276	        return map;
277	      }
278	      this.fail("Expecting ',' delimiter");
279	    }
280	  }
281	
282	  parseArray() {
283	    this.expect('[');
284	    const arr = [];
285	    this.skipWs();
286	    if (this.peek() === ']') {
287	      this.i++;
288	      return arr;
289	    }
290	    for (;;) {
291	      arr.push(this.parseValue());
292	      this.skipWs();
293	      const ch = this.peek();
294	      if (ch === ',') {
295	        this.i++;
296	        continue;
297	      }
298	      if (ch === ']') {
299	        this.i++;
300	        return arr;
301	      }
302	      this.fail("Expecting ',' delimiter");
303	    }
304	  }
305	
306	  hex4() {
307	    const h = this.s.slice(this.i, this.i + 4);
308	    if (h.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(h)) {
309	      this.fail('Invalid \\uXXXX escape');
310	    }
311	    this.i += 4;
312	    return Number.parseInt(h, 16);
313	  }
314	
315	  parseString() {
316	    this.expect('"');
317	    let out = '';
318	    for (;;) {
319	      if (this.i >= this.s.length) this.fail('Unterminated string starting at');
320	      const ch = this.s[this.i];
321	      if (ch === '"') {
322	        this.i++;
323	        return out;
324	      }
325	      if (ch === '\\') {
326	        this.i++;
327	        if (this.i >= this.s.length) this.fail('Unterminated string starting at');
328	        const esc = this.s[this.i];
329	        if (esc === 'u') {
330	          this.i++;
331	          const unit = this.hex4();
332	          if (unit >= 0xd800 && unit <= 0xdbff && this.s.startsWith('\\u', this.i)) {
333	            const save = this.i;
334	            this.i += 2;
335	            const low = this.hex4();
336	            if (low >= 0xdc00 && low <= 0xdfff) {
337	              out += String.fromCodePoint(
338	                0x10000 + ((unit - 0xd800) << 10) + (low - 0xdc00),
339	              );
340	              continue;
341	            }
342	            this.i = save;
343	          }
344	          out += String.fromCharCode(unit);
345	          continue;
346	        }
347	        const mapped = STRING_ESCAPES.get(esc);
348	        if (mapped === undefined) this.fail('Invalid \\escape');
349	        out += mapped;
350	        this.i++;
351	        continue;
352	      }
353	      if (ch < ' ') this.fail('Invalid control character at');
354	      out += ch;
355	      this.i++;
356	    }
357	  }
358	
359	  parseNumber() {
360	    const start = this.i;
361	    if (this.peek() === '-') this.i++;
362	    if (this.peek() === '0') {
363	      this.i++;
364	    } else if (this.peek() >= '1' && this.peek() <= '9') {
365	      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
366	    } else {
367	      this.fail('Expecting value');
368	    }
369	    let isFloat = false;
370	    if (this.peek() === '.') {
371	      isFloat = true;
372	      this.i++;
373	      if (!(this.peek() >= '0' && this.peek() <= '9')) this.fail('Expecting value');
374	      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
375	    }
376	    const e = this.peek();
377	    if (e === 'e' || e === 'E') {
378	      isFloat = true;
379	      this.i++;
380	      if (this.peek() === '+' || this.peek() === '-') this.i++;
381	      if (!(this.peek() >= '0' && this.peek() <= '9')) this.fail('Expecting value');
382	      while (this.peek() >= '0' && this.peek() <= '9') this.i++;
383	    }
384	    const raw = this.s.slice(start, this.i);
385	    // Integral literals (no '.', 'e' or 'E') become Python ints -> BigInt.
386	    return isFloat ? Number(raw) : BigInt(raw);
387	  }
388	}
389	
390	/**
391	 * CPython `json.loads()` for the project's data model.
392	 *
393	 * Objects become Maps in document order, arrays become Arrays, integer
394	 * literals become BigInt, other numbers become JS numbers.  Throws on
395	 * malformed input.
396	 *
397	 * @param {string} text
398	 * @returns {*}
399	 */
400	export function pyJsonLoads(text) {
401	  if (typeof text !== 'string') {
402	    throw new TypeError('the JSON object must be str');
403	  }
404	  const p = new JsonParser(text);
405	  const value = p.parseValue();
406	  p.skipWs();
407	  if (p.i !== text.length) p.fail('Extra data');
408	  return value;
409	}
