1	// Pure-JavaScript port of the parts of CPython's `textwrap` module that
2	// `argparse.HelpFormatter` relies on (`textwrap.wrap` / `textwrap.fill` with
3	// their default options).
4	//
5	// Mirrors CPython 3.11/3.12 Lib/textwrap.py:
6	//   expand_tabs=True, replace_whitespace=True, drop_whitespace=True,
7	//   break_long_words=True, break_on_hyphens=True, initial_indent='',
8	//   subsequent_indent='', fix_sentence_endings=False, max_lines=None.
9	//
10	// No external dependencies (ESM only).
11	
12	// Python: _whitespace = '\t\n\x0b\x0c\r '
13	const WHITESPACE = '\t\n\v\f\r ';
14	
15	// Character classes used to rebuild Python's `wordsep_re`.
16	const WS_CLASS = '[\\t\\n\\x0b\\x0c\\r ]'; // re.escape(_whitespace) equivalent
17	const NWS_CLASS = '[^\\t\\n\\x0b\\x0c\\r ]';
18	const WP_CLASS = '[\\w!"\'&.,?]'; // word_punct
19	const LT_CLASS = '[^\\d\\W]'; // letter
20	
21	// Python's textwrap.TextWrapper.wordsep_re (re.VERBOSE), one capturing group
22	// spanning the whole pattern.  `\Z` is translated to `$` (no multiline flag).
23	const WORDSEP_SOURCE =
24	  '(' +
25	  WS_CLASS + '+' +
26	  '|(?<=' + WP_CLASS + ')-{2,}(?=\\w)' +
27	  '|' + NWS_CLASS + '+?(?:' +
28	  '-(?:(?<=' + LT_CLASS + '{2}-)|(?<=' + LT_CLASS + '-' + LT_CLASS + '-))' +
29	  '(?=' + LT_CLASS + '-?' + LT_CLASS + ')' +
30	  '|(?=' + WS_CLASS + '|$)' +
31	  '|(?<=' + WP_CLASS + ')(?=-{2,}\\w)' +
32	  '))';
33	
34	const WORDSEP_RE = new RegExp(WORDSEP_SOURCE, 'g');
35	const WORDSEP_SIMPLE_RE = new RegExp('(' + WS_CLASS + '+)', 'g');
36	
37	// str.expandtabs(tabsize) -- column resets on '\n' and '\r'.
38	function expandTabs(text, tabsize = 8) {
39	  if (text.indexOf('\t') === -1) return text;
40	  let out = '';
41	  let col = 0;
42	  for (const ch of text) {
43	    if (ch === '\t') {
44	      if (tabsize > 0) {
45	        const pad = tabsize - (col % tabsize);
46	        out += ' '.repeat(pad);
47	        col += pad;
48	      }
49	    } else {
50	      out += ch;
51	      if (ch === '\n' || ch === '\r') col = 0;
52	      else col += 1;
53	    }
54	  }
55	  return out;
56	}
57	
58	// str.translate(unicode_whitespace_trans): every whitespace char -> ' '
59	function replaceWhitespace(text) {
60	  let out = '';
61	  for (const ch of text) {
62	    out += WHITESPACE.indexOf(ch) === -1 ? ch : ' ';
63	  }
64	  return out;
65	}
66	
67	// Python's re.split() for a pattern made of a single capturing group that
68	// spans the whole match: unmatched gaps and the captured groups are both kept.
69	function reSplitCapturing(regex, text) {
70	  const rx = new RegExp(regex.source, regex.flags.includes('g') ? regex.flags : regex.flags + 'g');
71	  const pieces = [];
72	  let last = 0;
73	  let m;
74	  rx.lastIndex = 0;
75	  while ((m = rx.exec(text)) !== null) {
76	    pieces.push(text.slice(last, m.index));
77	    pieces.push(m[1] === undefined ? '' : m[1]);
78	    last = m.index + m[0].length;
79	    if (m[0].length === 0) rx.lastIndex += 1;
80	  }
81	  pieces.push(text.slice(last));
82	  return pieces;
83	}
84	
85	function isBlank(s) {
86	  for (const ch of s) {
87	    if (WHITESPACE.indexOf(ch) === -1) return false;
88	  }
89	  return true;
90	}
91	
92	export class TextWrapper {
93	  constructor(options = {}) {
94	    const {
95	      width = 70,
96	      initialIndent = '',
97	      subsequentIndent = '',
98	      expandTabs: doExpandTabs = true,
99	      replaceWhitespace: doReplaceWhitespace = true,
100	      fixSentenceEndings = false,
101	      breakLongWords = true,
102	      dropWhitespace = true,
103	      breakOnHyphens = true,
104	      tabsize = 8,
105	      maxLines = null,
106	      placeholder = ' [...]',
107	    } = options;
108	    this.width = width;
109	    this.initialIndent = initialIndent;
110	    this.subsequentIndent = subsequentIndent;
111	    this.expandTabs = doExpandTabs;
112	    this.replaceWhitespace = doReplaceWhitespace;
113	    this.fixSentenceEndings = fixSentenceEndings;
114	    this.breakLongWords = breakLongWords;
115	    this.dropWhitespace = dropWhitespace;
116	    this.breakOnHyphens = breakOnHyphens;
117	    this.tabsize = tabsize;
118	    this.maxLines = maxLines;
119	    this.placeholder = placeholder;
120	  }
121	
122	  _mungeWhitespace(text) {
123	    if (this.expandTabs) text = expandTabs(text, this.tabsize);
124	    if (this.replaceWhitespace) text = replaceWhitespace(text);
125	    return text;
126	  }
127	
128	  _split(text) {
129	    const regex = this.breakOnHyphens ? WORDSEP_RE : WORDSEP_SIMPLE_RE;
130	    return reSplitCapturing(regex, text).filter((c) => c !== '');
131	  }
132	
133	  _handleLongWord(reversedChunks, curLine, curLen, width) {
134	    let spaceLeft;
135	    if (width < 1) spaceLeft = 1;
136	    else spaceLeft = width - curLen;
137	
138	    if (this.breakLongWords) {
139	      const chunk = reversedChunks[reversedChunks.length - 1];
140	      let end = spaceLeft;
141	      if (this.breakOnHyphens && chunk.length > spaceLeft) {
142	        // break after the last hyphen, but only if there are non-hyphens
143	        // before it
144	        const searchable = chunk.slice(0, Math.max(spaceLeft, 0));
145	        const hyphen = searchable.lastIndexOf('-');
146	        if (hyphen > 0) {
147	          let anyNonHyphen = false;
148	          for (const c of chunk.slice(0, hyphen)) {
149	            if (c !== '-') {
150	              anyNonHyphen = true;
151	              break;
152	            }
153	          }
154	          if (anyNonHyphen) end = hyphen + 1;
155	        }
156	      }
157	      curLine.push(chunk.slice(0, Math.max(end, 0)));
158	      reversedChunks[reversedChunks.length - 1] = chunk.slice(Math.max(end, 0));
159	    } else if (curLine.length === 0) {
160	      curLine.push(reversedChunks.pop());
161	    }
162	    // else: drop the long word
163	  }
164	
165	  _wrapChunks(chunks) {
