176	      }
177	    }
178	
179	    // reversed chunk stack: last element is the next chunk
180	    chunks = chunks.slice().reverse();
181	
182	    while (chunks.length > 0) {
183	      const curLine = [];
184	      let curLen = 0;
185	
186	      const indent = lines.length > 0 ? this.subsequentIndent : this.initialIndent;
187	      const width = this.width - indent.length;
188	
189	      if (this.dropWhitespace && isBlank(chunks[chunks.length - 1]) && lines.length > 0) {
