210	        curLine.pop();
211	      }
212	
213	      if (curLine.length > 0) {
214	        if (
215	          this.maxLines === null ||
216	          lines.length + 1 < this.maxLines ||
217	          ((chunks.length === 0 ||
218	            (this.dropWhitespace &&
219	              chunks.length === 1 &&
220	              isBlank(chunks[0]))) &&
221	            curLen <= width)
222	        ) {
223	          lines.push(indent + curLine.join(''));
224	        } else {
225	          let done = false;
226	          while (curLine.length > 0) {
227	            if (
