2	// reproduce, byte for byte, the behaviour of:
3	//
4	//     parser = argparse.ArgumentParser()
5	//     parser.add_argument('--subject', type=str, required=True)
6	//     parser.add_argument('--user_data', type=str, required=True)
7	//     args = parser.parse_args()
8	//
9	// The implementation follows CPython's Lib/argparse.py closely (help
10	// formatting geometry, usage line wrapping, prefix-abbreviation matching,
11	// error messages, exit codes and the stdout/stderr split).
