43	// Python's repr() for str (used by "ignored explicit argument %r").
44	function pyRepr(s) {
45	  const str = String(s);
46	  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";
47	  let out = '';
48	  for (const ch of str) {
49	    if (ch === '\\') out += '\\\\';
50	    else if (ch === quote) out += '\\' + ch;
51	    else if (ch === '\n') out += '\\n';
52	    else if (ch === '\r') out += '\\r';
53	    else if (ch === '\t') out += '\\t';
54	    else {
55	      const cp = ch.codePointAt(0);
56	      if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
57	      else out += ch;
58	    }
59	  }
60	  return quote + out + quote;
