67	  if (raw === undefined) return 0;
68	  const s = raw.replace(/^[\s]+/, '').replace(/[\s]+$/, '');
69	  if (!/^[+-]?\d+(?:_\d+)*$/.test(s)) return 0;
70	  const n = Number.parseInt(s.replace(/_/g, ''), 10);
71	  return Number.isNaN(n) ? 0 : n;
